const assert = require('assert');
const fs = require('fs');
const path = require('path');
const reportReaderJson = require('../reportReader-json');
const reportReaderNdJson = require('../reportReader-ndjson');

// reports are generated by test/fixtures/generate.js
const readers = {
    'json': reportReaderJson,
    'ndjson': reportReaderNdJson
};

for (const [extension, reportReader] of Object.entries(readers)) {
    function readReport(name) {
        const reportFile = path.join(__dirname, 'fixtures', 'reports', `${name}.${extension}`);
        return reportReader.reader(fs.readFileSync(reportFile));
    }

    describe(`reportReader-${extension}`, () => {
        describe('nominal report', () => {
            const report = readReport('nominal');

            it('should count scenarios by status', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.scenarioNumber, 7);
                assert.strictEqual(info.failedScenarioNumber, 2);
                assert.strictEqual(info.undefinedScenarioNumber, 3);
                assert.strictEqual(info.pendingScenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 1);
            });

            it('should count steps by status', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.stepsNumber, 9);
                assert.strictEqual(info.failedStepsNumber, 2);
                assert.strictEqual(info.skippedStepsNumber, 1);
                assert.strictEqual(info.undefinedStepsNumber, 3);
                assert.strictEqual(info.pendingStepNumber, 1);
                assert.strictEqual(info.succeedStepsNumber, 2);
            });

            it('should list failed steps', () => {
                const failedSteps = report.failedSteps
                    .map(({ file, line, title, step }) => ({ file, line, title, step }))
                    .sort((a, b) => a.file.localeCompare(b.file));
                assert.deepStrictEqual(failedSteps, [
                    {
                        file: 'cucumber/js/features/background.feature',
                        line: 4,
                        title: 'This scenario will fail because of background',
                        step: 'this step will fail'
                    },
                    {
                        file: 'cucumber/js/features/test.feature',
                        line: 10,
                        title: 'Scenario KO',
                        step: 'this step will fail'
                    }
                ]);
                for (const failedStep of report.failedSteps) {
                    assert.match(failedStep.error, /this step allways fail/);
                }
            });

            it('should list undefined steps', () => {
                assert.strictEqual(report.undefinedSteps.length, 3);
            });

            it('should list pending steps', () => {
                const pendingSteps = report.pendingSteps
                    .map(({ file, line, title, step }) => ({ file, line, title, step }));
                assert.deepStrictEqual(pendingSteps, [{
                    file: 'cucumber/js/features/test.feature',
                    line: 21,
                    title: 'Scenario with pending step',
                    step: 'this step is pending'
                }]);
            });

            it('should list all scenarios by file', () => {
                const scenarioByFile = report.listAllScenarioByFile
                    .sort((a, b) => a.file.localeCompare(b.file));
                assert.deepStrictEqual(scenarioByFile, [
                    {
                        file: 'cucumber/js/features/background.feature',
                        name: 'Test with background',
                        scenarios: [
                            { name: 'This scenario will fail because of background', status: 'failed' }
                        ]
                    },
                    {
                        file: 'cucumber/js/features/test.feature',
                        name: 'Test file',
                        scenarios: [
                            { name: 'Scenario OK', status: 'success' },
                            { name: 'Scenario KO', status: 'failed' },
                            { name: 'Scenario with undefined step', status: 'undefined' },
                            { name: 'Scenario with pending step', status: 'pending' },
                            { name: 'Scenario with Outline', status: 'undefined' },
                            { name: 'Scenario with Outline', status: 'undefined' }
                        ]
                    }
                ]);
            });
        });

        describe('scenario with several undefined steps', () => {
            const report = readReport('undefined-steps');

            it('should count the scenario once', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.scenarioNumber, 1);
                assert.strictEqual(info.undefinedScenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 0);
            });

            it('should count each undefined step', () => {
                assert.strictEqual(report.globalInformation.undefinedStepsNumber, 2);
            });
        });

        describe('scenario with a failing step and a failing after hook', () => {
            const report = readReport('failing-step-and-hook');

            it('should count the scenario once', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.scenarioNumber, 1);
                assert.strictEqual(info.failedScenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 0);
            });

            it('should not count hooks as steps', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.stepsNumber, 1);
                assert.strictEqual(info.failedStepsNumber, 1);
            });

            it('should list failed steps without error', () => {
                const failedSteps = report.failedSteps;
                assert.ok(failedSteps.length > 0);
                for (const failedStep of failedSteps) {
                    assert.strictEqual(failedStep.file, 'test/fixtures/features/failing-step-and-hook.feature');
                    assert.strictEqual(failedStep.title, 'Scenario failing in step and after hook');
                }
            });
        });

        describe('scenario with a failing before hook', () => {
            const report = readReport('failing-before-hook');

            it('should count the scenario as failed', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.scenarioNumber, 1);
                assert.strictEqual(info.failedScenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 0);
            });

            it('should not count hooks as steps', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.stepsNumber, 1);
                assert.strictEqual(info.skippedStepsNumber, 1);
            });

            it('should list the failure without error', () => {
                const failedSteps = report.failedSteps;
                assert.strictEqual(failedSteps.length, 1);
                assert.strictEqual(failedSteps[0].file, 'test/fixtures/features/failing-before-hook.feature');
                assert.strictEqual(failedSteps[0].title, 'Scenario failing in before hook');
                assert.match(failedSteps[0].error, /this before hook allways fail/);
            });

            it('should annotate the failing hook on the scenario line', () => {
                const failedStep = report.failedSteps[0];
                assert.strictEqual(failedStep.step, 'Before hook');
                assert.strictEqual(failedStep.line, 4);
            });
        });

        describe('scenario with passing hooks', () => {
            const report = readReport('passing-hooks');

            it('should not count hooks as steps', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.stepsNumber, 1);
                assert.strictEqual(info.succeedStepsNumber, 1);
            });

            it('should count the scenario as passed', () => {
                assert.strictEqual(report.globalInformation.succeedScenarioNumber, 1);
            });
        });

        describe('feature with rule', () => {
            it('should read the report without error', () => {
                assert.doesNotThrow(() => readReport('rule'));
            });

            it('should count scenarios inside the rule', () => {
                const info = readReport('rule').globalInformation;
                assert.strictEqual(info.scenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 1);
                assert.strictEqual(info.stepsNumber, 1);
            });

            it('should list scenarios inside the rule', () => {
                assert.deepStrictEqual(readReport('rule').listAllScenarioByFile, [{
                    file: 'test/fixtures/features/rule.feature',
                    name: 'Feature with rule',
                    scenarios: [{ name: 'Scenario inside a rule', status: 'success' }]
                }]);
            });
        });

        describe('scenario retried', () => {
            const report = readReport('retry');

            it('should count the scenario once', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.scenarioNumber, 1);
                assert.strictEqual(info.failedScenarioNumber, 1);
                assert.strictEqual(info.succeedScenarioNumber, 0);
            });

            it('should only count steps of the last attempt', () => {
                const info = report.globalInformation;
                assert.strictEqual(info.stepsNumber, 1);
                assert.strictEqual(info.failedStepsNumber, 1);
            });

            it('should list the failure once', () => {
                assert.strictEqual(report.failedSteps.length, 1);
            });
        });
    });
}
